    elseif target.get_x ~= nil then
        targetPos = {
            x = target:get_x(),
            y = target:get_y()
        }
    elseif target.get_point ~= nil then
        local point = target:get_point()
        targetPos = {
            x = point:get_x(),
            y = point:get_y()
        }
    else
        targetPos = {x = target.x, y = target.y}
    end
    local vAB = {x = targetPos.x - pos.x, y = targetPos.y - pos.y}
    local vAO = {
        x = math.sin(angle / 180 * math.pi),
        y = math.cos(angle / 180 * math.pi)
    }
    local dotP = vAB.x * vAO.x + vAB.y * vAO.y
    return dotP > 0
end
